const KX = 111.32 * Math.cos((GEO.bbox[1] + GEO.bbox[3]) / 2 * Math.PI / 180), KY = 110.57;
const xy = (lat, lon) => [+((lon - GEO.bbox[0]) * KX / GEO.kmPerUnit).toFixed(1), +((GEO.bbox[3] - lat) * KY / GEO.kmPerUnit).toFixed(1)];
const sec = (id, name, lat, lon, o) => { const [x, y] = xy(lat, lon); return { id, name, latlon: [lat, lon], x, y, ...o }; };
const lbl = (lat, lon, text, size = 9) => { const [x, y] = xy(lat, lon); return { x, y, text, size }; };
const unit = (uid, key, name, kind, men, veh, xp = 0) => ({
  uid, key, name, kind, men, menMax: men, wounded: 0,
  ...(veh ? { veh: { kind: veh, hp: 1, lost: false } } : {}),
  xp, battles: 0, kills: 0, status: 'ready',
});
const arriving = (u, eta) => ({ ...u, status: 'arriving', eta });

